-- 설정이 조립한다

@Configuration
public class ProxyConfig {

    @Bean
    public OrderService orderService(LogTrace trace) {
        OrderServiceImpl impl = new OrderServiceImpl(orderRepository(trace));
        return new OrderServiceProxy(impl, trace);
    }

    @Bean
    public OrderRepository orderRepository(LogTrace trace) {
        OrderRepositoryImpl impl = new OrderRepositoryImpl();
        return new OrderRepositoryProxy(impl, trace);
    }
}

